-- Insert additional pre-order vehicles
-- Run via: SUPABASE_PAT=sbp_xxx node scripts/insert-blog-post.mjs  (or paste into Supabase SQL Editor)


-- Add a cover image for each pre-order vehicle just inserted
SELECT id, 'image', 'https://images.unsplash.com/photo-1636578929419-fc62088fd08f?w=800&h=600&fit=crop', 0, true, make || ' ' || model
FROM vehicles WHERE status = 'pre-order' AND NOT EXISTS (
  SELECT 1 FROM vehicle_media vm WHERE vm.vehicle_id = vehicles.id
);

SELECT 'PRE-ORDER VEHICLES' AS table_name, COUNT(*) AS count FROM vehicles WHERE status = 'pre-order';
